/**
 * @distilled.cloud/growthbook — GrowthBook REST API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model
 * in `.generated-specs` (written by `scripts/convert.ts` from the OpenAPI
 * spec). Everything else in this folder is hand-written.
 *
 * @example
 * ```ts
 * import * as GrowthBook from "@distilled.cloud/growthbook";
 *
 * const features = yield* GrowthBook.Services.growthbook.listFeaturesV2({});
 * ```
 */
export {
  Credentials,
  CredentialsFromEnv,
  DEFAULT_API_BASE_URL,
  fromApiKey,
} from "./credentials.ts";
export type { Config as GrowthBookClientConfig } from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  GrowthBookProtocol,
  type GrowthBookOpError,
  type GrowthBookOpContext,
} from "./protocol.ts";
export { paginateToken } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * as Services from "./services/index.ts";
// Operations (and their request/response types) are importable straight off
// the package root. The service-local typed error classes shadow the
// same-named shared ones from ./errors.ts — the ops actually raise the
// service-local classes.
export * from "./services/growthbook.ts";
export {
  BadRequest,
  Conflict,
  Forbidden,
  NotFound,
} from "./services/growthbook.ts";
